import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第二册：实践与进步 · Lesson 90 What's for supper?","description":"学习 分词修饰与逻辑主语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 90 What's for supper?","description":"学习 分词修饰与逻辑主语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 分词修饰与逻辑主语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 89 A slip of the tongue","link":"/life/english/new-concept/book-2/unit-04/lesson-089"},"next":{"text":"第二册：实践与进步 · Lesson 91 Three men in a basket","link":"/life/english/new-concept/book-2/unit-04/lesson-091"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 89 A slip of the tongue","link":"/life/english/new-concept/book-2/unit-04/lesson-089"},"next":{"text":"第二册：实践与进步 · Lesson 91 Three men in a basket","link":"/life/english/new-concept/book-2/unit-04/lesson-091"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-090.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-090.md"}`),i={name:"life/english/new-concept/book-2/unit-04/lesson-090.md"};function r(s,e,l,d,h,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-90-what-s-for-supper" tabindex="-1">第二册：实践与进步 · Lesson 90 What&#39;s for supper? <a class="header-anchor" href="#第二册-实践与进步-·-lesson-90-what-s-for-supper" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 90 What&#39;s for supper?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>食物供应变化导致晚餐临时调整，说明事实时应区分原因和猜测；练习现在分词与被动。本课的语言观察是：fried potatoes 中 fried 表经过油炸处理的状态；frying potatoes 可指正在炸土豆的动作，不能仅看 -ing 就当形容词。完成学习后，请写三句临时菜单调整，说明已有食材、用完的食材和新的搭配。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>supper</td><td>/ˈsʌpə/</td><td>n.</td><td>晚餐</td><td>prepare supper</td></tr><tr><td>oil</td><td>/ɔɪl/</td><td>n.</td><td>油</td><td>cooking oil</td></tr><tr><td>chip</td><td>/tʃɪp/</td><td>n.</td><td>炸薯条；碎片</td><td>a bag of chips</td></tr><tr><td>fry</td><td>/fraɪ/</td><td>v.</td><td>油炸</td><td>fry potatoes</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>run out of — 用完，主语通常是使用者</li><li>be used for — 用于，for 后可接名词或 -ing</li></ul><h2 id="语法讲解-分词修饰与逻辑主语" tabindex="-1">语法讲解：分词修饰与逻辑主语 <a class="header-anchor" href="#语法讲解-分词修饰与逻辑主语" aria-label="Permalink to &quot;语法讲解：分词修饰与逻辑主语&quot;">​</a></h2><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：fried potatoes 中 fried 表经过油炸处理的状态；frying potatoes 可指正在炸土豆的动作，不能仅看 -ing 就当形容词。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The potatoes fried this morning were used for supper.</p></blockquote><p>今天早上炸好的土豆被用于晚餐。</p><p>fried this morning 是过去分词后置定语，were used 才是主句谓语，主语 potatoes 为复数。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>We ran out potatoes 缺 of；Potatoes ran out 是另一种主语安排。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读出 potatoes 的词尾 /z/，将 fried this morning 作为一个修饰语块。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The potatoes fried this morning were used for supper. The cook added vegetables and a fresh sauce. There was no fish left in the kitchen.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句临时菜单调整，说明已有食材、用完的食材和新的搭配。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：fried this morning 是过去分词后置定语，were used 才是主句谓语，主语 potatoes 为复数。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：We ran out potatoes 缺 of；Potatoes ran out 是另一种主语安排。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>主句谓语是 fried 还是 were used？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were used</p><p><strong>解析：</strong> fried this morning 修饰 potatoes，were used 完成主句断言。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>厨房还有鱼吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No.</p><p><strong>解析：</strong> no fish left 说明库存为零，不能推出此前无人送鱼。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用 run out of 说“我们用完了食用油”。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We have run out of cooking oil.</p><p><strong>解析：</strong> run out of 接已经用完的物品。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：分词修饰与逻辑主语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-089">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-091">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=t(i,[["render",r]]);export{u as __pageData,f as default};
